      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.20 vs baseline (peak A/E 1.20)",
      "confidence": 0.85,
      "evidence": [
        "ae_ip_by_year.csv shows sustained 4-year climb from 1.04 to 1.20; empirical SD 0.12 vs Poisson 0.026 (x4.5 overdispersion) means Poisson null is invalid, but excursion score 5.3 confirms sustained level shift"
      ],
      "recommended_action": "Review IP onset/duration assumptions and claim trends; assess external factors driving 2019-2022 volume; verify that 2023-2024 reversion indicates stability or emerging volatility"
    }
  ]
